// Build the caption enhancement + spatial analysis request for a reference image.
// Called once per image when seeding or when a new reference is imported.
const ctx  = $('When Executed by Another Workflow').item.json;
const bin  = $input.item.binary.image;
const b64  = bin.data;
const mime = bin.mimeType || 'image/jpeg';
const dataUri = `data:${mime};base64,${b64}`;

const SYSTEM = `You are an interior-design visual analyst specialising in 3D spatial structure.

Your job: analyse the provided reference interior design image and produce two outputs.

1. ENHANCED_CAPTION (3-5 sentences):
   Cover ALL of these in natural flowing sentences:
   - Visual style and design intent (e.g. Japandi, Scandinavian, industrial)
   - Material palette: surface finishes, textures, dominant materials
   - Furniture arrangement and functional zones
   - Colour story: dominant hues, accent colours, tonal range
   - Natural light quality: source direction, intensity, time-of-day feel
   - Mood and atmosphere

2. SPATIAL_SIGNATURE (JSON object, no code fences):
   Describe the 3D geometry of the room visible in the image.
   Use ONLY these exact keys and value options:
   {
     "room_shape": "rectangular" | "square" | "L-shaped" | "open-plan",
     "depth_cues": "strong" | "moderate" | "minimal",
     "ceiling_height": "low" | "standard" | "high" | "vaulted",
     "window_wall": "left" | "right" | "back" | "front" | "multiple" | "none",
     "light_direction": "front-left" | "front-right" | "back-left" | "back-right" | "overhead" | "diffuse",
     "focal_wall": "front" | "left" | "right" | "ceiling",
     "floor_visible_pct": <integer 0-100>,
     "symmetry": "symmetric" | "asymmetric" | "partial",
     "open_to": [<array of adjacent spaces, e.g. "dining", "kitchen", "hallway">, or []]
   }

Output — STRICT. No extra text. Exactly:
===CAPTION===
<enhanced caption>
===END===

===SPATIAL===
<JSON object>
===END===`;

const openrouter_body = {
  model: 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: [
      { type: 'text', text: `Reference image ID: ${ctx.reference_image_id}\n${ctx.caption ? `Existing caption: ${ctx.caption}\n` : ''}Please analyse this interior design image.` },
      { type: 'image_url', image_url: { url: dataUri } }
    ]}
  ],
  temperature: 0.3,
  max_tokens: 1024
};

return [{ json: { ...ctx, openrouter_body } }];

// Parse ===CAPTION=== and ===SPATIAL=== blocks from LLM response.
const ctx     = $('Build enhancement request').item.json;
const content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';

if (!content) {
  return [{ json: { ...ctx, _error: 'empty_response' } }];
}

function extractBlock(text, tag) {
  const startRe = new RegExp(`={3,}\\s*${tag}\\s*={3,}`, 'i');
  const endRe   = /={3,}\s*END\s*={3,}/i;
  const s = text.search(startRe);
  if (s < 0) return null;
  const after = text.slice(s).replace(startRe, '');
  const e = after.search(endRe);
  return e < 0 ? after.trim() : after.slice(0, e).trim();
}

const caption_enhanced = extractBlock(content, 'CAPTION');
const spatialRaw       = extractBlock(content, 'SPATIAL');

if (!caption_enhanced) {
  return [{ json: { ...ctx, _error: 'missing_caption_block', raw: content.slice(0, 300) } }];
}

let spatial_signature = null;
if (spatialRaw) {
  try {
    spatial_signature = JSON.parse(spatialRaw);
  } catch (_) {
    // Best-effort: store null if JSON is malformed
  }
}

return [{ json: { ...ctx, caption_enhanced, spatial_signature, _error: null } }];

// Log parse failure — do not throw, just return so the seed loop continues.
const ctx = $json;
console.error(`wf_enhance_caption: parse failed for ${ctx.reference_image_id}: ${ctx._error}`);
return [{ json: { reference_image_id: ctx.reference_image_id, ok: false, error: ctx._error } }];
